function resolvePlaceholder(s) {
  if (s.startsWith(".") || s.startsWith("http"))
    return { grad: "real", url: s, emoji: "👗" };
  const p = s.split(":");
  return { grad: p[1] || "g1", emoji: p[2] || "👗", url: "" };
}

/* ============================================================
   SISTEMA DE TALLAS, DESCUENTOS Y ETIQUETAS
   ------------------------------------------------------------
   Aplica únicamente a: Cardigans, Casacas, Jeans y Conjuntos de
   Invierno (Niño/Niña). El resto de categorías (ej. Vestidos)
   no se modifica.
   ============================================================ */

// Categorías donde el panel de administración puede editar
// precio de oferta, tallas y etiqueta.
const ADMIN_MANAGED_CATEGORIES = [
  "cardigans-nina",
  "cardigans-nino",
  "casacas-nina",
  "casacas-nino",
  "jeans-nina",
  "jeans-nino",
  "conjuntos-invierno-nina",
  "conjuntos-invierno-nino",
];

// Tallas disponibles para el filtro y el panel de administración,
// en el orden en que deben mostrarse.
const AVAILABLE_SIZES = [
  "12-18 Meses",
  "18-24 Meses",
  "2 Años",
  "3 Años",
  "4 Años",
  "5 Años",
  "6 Años",
  "7 Años",
  "8 Años",
  "9 Años",
];

// Etiquetas de producto: valor guardado en p.badge -> emoji + texto a mostrar.
const BADGE_INFO = {
  "": null,
  nuevo: { emoji: "🆕", label: "Nuevo Ingreso" },
  tendencia: { emoji: "🔥", label: "Tendencia" },
  liquidacion: { emoji: "🏷", label: "Liquidación" },
};
function badgeDisplay(badge) {
  const info = BADGE_INFO[badge || ""];
  return info ? `${info.emoji} ${info.label}` : "";
}

/* ---------- Overrides del panel de administración (localStorage) ----------
   El panel de administración (admin.html) no tiene backend, así que guarda
   sus cambios (precio de oferta, tallas activas y etiqueta) en localStorage.
   Aquí los aplicamos sobre PRODUCTS al cargar cualquier página del sitio. */
const ADMIN_OVERRIDES_KEY = "mariekids_admin_overrides";

function loadAdminOverrides() {
  try {
    return JSON.parse(localStorage.getItem(ADMIN_OVERRIDES_KEY) || "{}");
  } catch (e) {
    return {};
  }
}

function saveAdminOverride(productId, patch) {
  const all = loadAdminOverrides();
  all[productId] = { ...(all[productId] || {}), ...patch };
  localStorage.setItem(ADMIN_OVERRIDES_KEY, JSON.stringify(all));
}

function applyAdminOverrides() {
  const overrides = loadAdminOverrides();
  PRODUCTS.forEach((p) => {
    const o = overrides[p.id];
    if (!o) return;
    if (typeof o.price === "number") p.price = o.price;
    if (o.oldPrice === null || typeof o.oldPrice === "number")
      p.oldPrice = o.oldPrice;
    if (Array.isArray(o.sizes)) {
      p.sizes = o.sizes;
      p.ageGroup = o.sizes;
    }
    if (typeof o.badge === "string") p.badge = o.badge;
  });
}
applyAdminOverrides();
